package com.nyayaconnect.document;
import com.nyayaconnect.auth.SpringAccess;import com.nyayaconnect.casemgmt.CaseAccessService;import com.nyayaconnect.common.*;import com.nyayaconnect.security.*;import jakarta.servlet.http.*;import java.io.*;import java.nio.file.*;import java.util.*;
public class DocumentUploadServlet extends HttpServlet {private CaseAccessService access;private DocumentIntegrityService integrity;private DocumentDao documents;public void init(){access=SpringAccess.bean(getServletContext(),CaseAccessService.class);integrity=SpringAccess.bean(getServletContext(),DocumentIntegrityService.class);documents=SpringAccess.bean(getServletContext(),DocumentDao.class);}
 protected void doPost(HttpServletRequest req,HttpServletResponse res)throws IOException, jakarta.servlet.ServletException{try{SessionUser u=(SessionUser)req.getSession(false).getAttribute(AuthenticationFilter.SESSION_KEY);UUID caseId=UUID.fromString(req.getParameter("caseId"));access.requireAccess(u,caseId);Part part=req.getPart("file");if(part==null||part.getSize()==0)throw new IllegalArgumentException("A document is required.");String ct=Optional.ofNullable(part.getContentType()).orElse("application/octet-stream");Set<String> allowed=Set.of("application/pdf","image/png","image/jpeg","text/plain");if(!allowed.contains(ct))throw new IllegalArgumentException("Unsupported file type.");String original=Optional.ofNullable(part.getSubmittedFileName()).orElse("document").replaceAll("[^A-Za-z0-9._ -]","_");String key=caseId+"/"+UUID.randomUUID()+"-"+original;Path target=integrity.safePath(key);Files.createDirectories(target.getParent());try(InputStream in=part.getInputStream()){String hash=integrity.sha256(in);validateMagic(part,ct);try(InputStream copy=part.getInputStream()){Files.copy(copy,target,StandardCopyOption.REPLACE_EXISTING);}UUID documentId=documents.insert(caseId,original,key,ct,part.getSize(),hash,u.id());documents.accessLog(documentId,u.id(),"UPLOAD",req.getRemoteAddr());Api.json(res,201,Map.of("documentId",documentId,"originalName",original,"storageKey",key,"sha256",hash,"sizeBytes",part.getSize()));}}catch(SecurityException e){Api.error(res,403,"FORBIDDEN",e.getMessage());}catch(IllegalArgumentException e){Api.error(res,400,"INVALID_DOCUMENT",e.getMessage());}catch(Exception e){Api.error(res,500,"UPLOAD_FAILED","Document upload failed safely.");}}
 private static void validateMagic(Part p,String ct)throws IOException{if(ct.equals("text/plain"))return;try(InputStream in=p.getInputStream()){byte[] h=in.readNBytes(8);if(ct.equals("application/pdf") && !(h.length>=4&&h[0]==37&&h[1]==80&&h[2]==68&&h[3]==70))throw new IllegalArgumentException("PDF signature validation failed.");if(ct.equals("image/png") && !(h.length>=8&&h[0]==(byte)137&&h[1]==80&&h[2]==78&&h[3]==71&&h[4]==13&&h[5]==10&&h[6]==26&&h[7]==10))throw new IllegalArgumentException("PNG signature validation failed.");if(ct.equals("image/jpeg") && !(h.length>=3&&(h[0]&255)==255&&(h[1]&255)==216&&(h[2]&255)==255))throw new IllegalArgumentException("JPEG signature validation failed.");}}
}

